"""One disclosed planning revision, before any EXP2 random data; preserve v1."""
from pathlib import Path
root=Path(__file__).resolve().parents[2];out=root/'experiments/exp2'
assert not (out/'budget_start.json').exists() and not (out/'smoke_rows.jsonl').exists()
p=out/'design.py';s=p.read_text().replace('LOW_SEEDS=16','LOW_SEEDS=16\nP2_SEEDS=112');p.write_text(s)
p=out/'run.py';s=p.read_text()
s=s.replace('def cases(z,s,high,mom,budget):','def cases(z,s,high,mom,budget,p2alpha=None):')
s=s.replace('for a in ((.6,1.5) if high else (.2,.6,1.2,1.5)):','for a in ((p2alpha,) if p2alpha is not None else ((.6,1.5) if high else (.2,.6,1.2,1.5))):')
s=s.replace("        yield (f'Sign2_a{a:g}_proxy',proxy,q,c,None,dict(alpha=a,T=2))", "        if p2alpha is None:yield (f'Sign2_a{a:g}_proxy',proxy,q,c,None,dict(alpha=a,T=2))")
s=s.replace('    for p in mom:\n        if high', '    if p2alpha is not None:return\n    for p in mom:\n        if high',1)
s=s.replace('m=M,check_dense=False):','m=M,check_dense=False,p2only=False):')
s=s.replace('for name,u,q,c,proxy,params in cases(z,s,high,mom,budget):','for name,u,q,c,proxy,params in cases(z,s,high,mom,budget,(.6 if d==128 else 1.5) if p2only else None):')
s=s.replace("[(32,1.,0,False),(128,1.,1,False)]", "[(32,1.,0,False,False),(128,1.,1,False,False)]")
s=s.replace('tasks.extend((d,k,seed,d==512) for', 'tasks.extend((d,k,seed,d==512,False) for')
s=s.replace('tasks.extend((512,k,seed,True) for', 'tasks.extend((512,k,seed,True,False) for')
s=s.replace("    completed=0;error=None;checks={};resources=resource_meta()", "        tasks.extend((d,k,seed,False,True) for seed in range(16,P2_SEEDS) for d,k in ((128,1.),(128,2.),(256,1.),(256,2.)))\n    completed=0;error=None;checks={};resources=resource_meta()")
s=s.replace('for d,k,seed,high in tasks:', 'for d,k,seed,high,p2only in tasks:')
s=s.replace('high,mom,budget)\n                    for item', 'high,mom,budget,p2only=p2only)\n                    for item')
p.write_text(s)
p=out/'analyze.py';s=p.read_text()
s=s.replace('def paired(d,k,name,base,metric,m=512):','def paired(d,k,name,base,metric,m=512,include_extra=False):')
s=s.replace("        for seed in sorted(aa.keys()&bb.keys()):", "        for seed in sorted(aa.keys()&bb.keys()):\n            if d<512 and seed>=16 and not include_extra:continue")
s=s.replace("f['baseline'],f['metric']);mean,se=stat(dd)", "f['baseline'],f['metric'],include_extra=True);mean,se=stat(dd)")
s=s.replace("f['baseline'],f['metric']);n=len(dd)", "f['baseline'],f['metric'],include_extra=f['kind']=='P2');n=len(dd)")
s=s.replace("24 if d==512 else 16", "24 if d==512 else P2_SEEDS",2) # p2 planned + direction n
s=s.replace("expected=24 if d==512 else 16", "expected=24 if d==512 else (P2_SEEDS if f['kind']=='P2' else 16)")
s=s.replace("        if 'actual' not in name:continue\n        sign=", "        if 'actual' not in name:continue\n        rr={seed:r for seed,r in rr.items() if d==512 or seed<16}\n        sign=")
s=s.replace("rr=groups.get((dim,k,name),{});values.append", "rr={seed:r for seed,r in groups.get((dim,k,name),{}).items() if seed<16};values.append")
s=s.replace("expected_rows=4272,expected_configurations=144,complete=meta['completed']==144 and len(rows)==4272", "expected_rows=5040,expected_configurations=528,complete=meta['completed']==528 and len(rows)==5040")
s=s.replace("}/144 数据配置、{len(rows)}/4272", "}/528 数据配置、{len(rows)}/5040")
s=s.replace('使用16个低维种子、24个高维种子和512查询', 'P3使用16个低维种子、24个高维种子和512查询；P2四个原失败条件使用112个低维种子')
s=s.replace('512查询、16新种子','512查询、112新种子')
p.write_text(s)
p=out/'prepare.py';s=p.read_text()
s=s.replace("assert not (ROOT/'PREREG_EXP2.md').exists()", "assert not (OUT/'budget_start.json').exists()\nassert (OUT/'predata_v1/PREREG_EXP2.md').exists()")
s=s.replace("ns=LOW_SEEDS;z=", "ns=P2_SEEDS if kind=='P2' else LOW_SEEDS;z=")
s=s.replace('冻结时间 TIME。', '冻结时间 TIME。最初只含16个低维种子的规划版散列为12f9dc764f65846231000ddc0e5837f33a82fdd3007a934b52b5bf8953e472c5，保存在experiments/exp2/predata_v1；其事前功效表发现P2三项不足80%，因此在任何EXP2随机数据生成前，仅增补四个P2原失败条件到112种子，再冻结本最终版本；无新数据驱动的改门槛或选样。')
s=s.replace('共144数据配置。', '随后补P2定向配置：seed=16..111，依次d128/k1、d128/k2（只测Sign1和Sign2 alpha=.6真实），d256/k1、d256/k2（只测Sign1和Sign2 alpha=1.5真实）。同seed=0..15的P2数据复用全网格记录，不重复计数；P3分析严格只取低维seed<16。最终共528数据配置、5040方法记录。')
s=s.replace('512查询、16新种子', '512查询、112新种子')
s=s.replace('144配置和预定方法/种子齐全', '528配置、5040方法记录和预定方法/种子齐全')
s=s.replace('原d/k/alpha/q的512查询、16新种子', '原d/k/alpha/q的512查询、112新种子')
p.write_text(s)
for p in out.glob('*.py'):compile(p.read_text(),str(p),'exec')
print('predata-only revision: no experimental data files exist; v1 preserved')
